package main

import (
	"context"
	"log"
	"net"

	pb "github.com/jelb30/Mosaic/proto"
	"github.com/jelb30/Mosaic/storage"
	"google.golang.org/grpc"
)

// server binds our gRPC network interface to our storage engine.
// It implements the pb.KVStoreServer interface generated by Protobuf.
type server struct {
	pb.UnimplementedKVStoreServer // Required by gRPC for forward compatibility
	store                         *storage.KVStore
}

// Put handles incoming network write requests
func (s *server) Put(ctx context.Context, req *pb.PutRequest) (*pb.PutResponse, error) {
	s.store.Put(req.Key, req.Value)
	return &pb.PutResponse{Success: true}, nil
}

// Get handles incoming network read requests
func (s *server) Get(ctx context.Context, req *pb.GetRequest) (*pb.GetResponse, error) {
	val, exists := s.store.Get(req.Key)
	return &pb.GetResponse{Value: val, Found: exists}, nil
}

func main() {
	// 1. Open a TCP network port on port 50051
	lis, err := net.Listen("tcp", ":50052")
	if err != nil {
		log.Fatalf("failed to listen: %v", err)
	}

	// 2. Initialize our ultra-fast memory database
	kvStore := storage.NewKVStore()

	// 3. Create the gRPC server and register our service mapping
	grpcServer := grpc.NewServer()
	pb.RegisterKVStoreServer(grpcServer, &server{store: kvStore})

	log.Println("Mosaic Node listening on port 50052...")

	// 4. Start serving requests (This blocks the thread forever)
	if err := grpcServer.Serve(lis); err != nil {
		log.Fatalf("failed to serve: %v", err)
	}
}
